tileidx_t tile_main_enchanted(tileidx_t idx, int ench)
{
    int num_pairs = sizeof(main_enchant_pairs) / sizeof(main_enchant_pairs[0]);
    tile_variation key(idx, ench);
    tileidx_t found;
    bool result = binary_search<tile_variation, tileidx_t>(
       key, &main_enchant_pairs[0], num_pairs,
       &tile_variation::cmp, &found);
    return (result ? found : idx);
}

